schema_ddl:
CREATE TABLE ITP (
    ITEMN INT,
    PONUM INT,
    PRIMARY KEY (ITEMN)
);
CREATE TABLE ITL (
    ITEMN INT,
    WKCEN INT,
    LOCAN INT
);

counterexample:
